import { Account, Client } from 'appwrite';

const client = new Client()
  .setEndpoint('https://cloud.appwrite.io/v1')
  .setProject(process.env.APPWRITE_PROJECT_ID!);
const account = new Account(client);

await account.createEmailPasswordSession(huesped.email, huesped.password);

app.post('/webhooks/appwrite/users', express.json(), async (req, res) => {
  if (!isValidSignature(req.get('X-Appwrite-Webhook-Signature'), req)) return res.sendStatus(401);
  const user = req.body;
  await createEmployeeRecord({ email: user.email, name: user.name });
  res.sendStatus(200);
});
